-- A sheet's periods: a name unique on the sheet and a from and to date, both inclusive. No two
-- periods on a sheet overlap, so a claim belongs to the one period whose dates contain its date,
-- or to none.
CREATE TABLE period (
    sheet_id  VARCHAR(200) NOT NULL,
    name      VARCHAR(200) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    PRIMARY KEY (sheet_id, name)
);
package net.officefloor.hq.app.period;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidPeriod {
    public void handle(@Parameter InvalidPeriodException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}
package net.officefloor.hq.app.period;

/** A period that cannot be added (no name, a name already on the sheet, a bad date, a from-date after
 *  its to-date, or dates overlapping another period); nothing is written. */
public class InvalidPeriodException extends Exception {
    public InvalidPeriodException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.period;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPeriods {
