            ObjectResponse<List<PeriodResponse>> response) {
        response.send(periods.list(sheetId));
    }
}
package net.officefloor.hq.app.period;

/** Body of POST /api/sheets/{sheetId}/periods: the period's name and its from and to dates
 *  (YYYY-MM-DD, both inclusive). */
public record PeriodRequest(String name, String from, String to, String user) {
}
package net.officefloor.hq.app.period;

/** A period: its name and its from and to dates (YYYY-MM-DD, both inclusive). */
public record PeriodResponse(String name, String from, String to) {
}
package net.officefloor.hq.app.period;

import java.sql.Date;
import java.util.List;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The period store: named, non-overlapping date ranges (both ends inclusive), kept per sheet. */
@Repository
public class Periods {

    private final JdbcTemplate jdbc;

    public Periods(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's periods, by from-date. */
    public List<PeriodResponse> list(String sheetId) {
        return jdbc.query("SELECT name, from_date, to_date FROM period WHERE sheet_id = ? ORDER BY from_date",
                (rs, i) -> new PeriodResponse(rs.getString("name"), rs.getDate("from_date").toLocalDate().toString(),
                        rs.getDate("to_date").toLocalDate().toString()),
                sheetId);
    }

    /** Add a period, refusing a name already on the sheet or dates overlapping another period. */
    public void add(String sheetId, ValidPeriod period) throws InvalidPeriodException {
        // Lock the sheet's row so two periods added at once cannot both pass the overlap check.
        jdbc.query("SELECT id FROM sheet WHERE id = ? FOR UPDATE", (rs, i) -> rs.getString(1), sheetId);
        Integer named = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND name = ?",
                Integer.class, sheetId, period.name());
        if (named != null && named > 0) {
            throw new InvalidPeriodException("A period named " + period.name() + " is already on the sheet");
        }
        Integer overlapping = jdbc.queryForObject(
                "SELECT COUNT(*) FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ?",
                Integer.class, sheetId, Date.valueOf(period.to()), Date.valueOf(period.from()));
        if (overlapping != null && overlapping > 0) {
            throw new InvalidPeriodException("The period's dates overlap another period");
        }
        try {
            jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date) VALUES (?, ?, ?, ?)",
                    sheetId, period.name(), Date.valueOf(period.from()), Date.valueOf(period.to()));
        } catch (DuplicateKeyException raced) {
            throw new InvalidPeriodException("A period named " + period.name() + " is already on the sheet");
        }
    }
}
package net.officefloor.hq.app.period;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class SavePeriod {
    public void save(@PathVariable("sheetId") String sheetId, @Val ValidPeriod period, Periods periods, Audit audit,
            ObjectResponse<List<PeriodResponse>> response) throws InvalidPeriodException {
        periods.add(sheetId, period);
        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + period.user()
                + " period=" + period.name() + " from=" + period.from() + " to=" + period.to());
        response.send(periods.list(sheetId));
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePeriod {

    private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("uuuu-MM-dd")
            .withResolverStyle(ResolverStyle.STRICT);

    public void validate(@RequestBody PeriodRequest request, Out<ValidPeriod> body) throws InvalidPeriodException {
        String name = request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) {
            throw new InvalidPeriodException("A period needs a name");
        }
        LocalDate from = date(request.from(), "from");
        LocalDate to = date(request.to(), "to");
        if (from.isAfter(to)) {
            throw new InvalidPeriodException("The from-date must be on or before the to-date");
        }
        body.set(new ValidPeriod(name, from, to, request.user()));
    }

    private static LocalDate date(String raw, String which) throws InvalidPeriodException {
        try {
            return LocalDate.parse(raw == null ? "" : raw.trim(), DATE);
        } catch (DateTimeParseException e) {
            throw new InvalidPeriodException("The " + which + "-date must be a date (YYYY-MM-DD)");
        }
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;

/** A period that passed validation: a name and a from-date on or before its to-date. */
public record ValidPeriod(String name, LocalDate from, LocalDate to, String user) {
}
