      <button type="button" data-testid="claim-settle" onClick={() => act(() => status.mutate('settle'))}>
        Settle
      </button>{' '}
      <button type="button" data-testid="claim-void" onClick={() => act(() => status.mutate('void'))}>
        Void
      </button>{' '}
      {editing === c.id ? (
